create function public.set_vnext_watch_v1(p_observation_id text,p_watching boolean) returns jsonb
language plpgsql security definer set search_path='' as $$
declare tier text; previous boolean; n integer;
begin
 tier:=academy_private.access_v11();
 if auth.uid() is null or tier is null or tier not in('premium','owner') then raise exception 'PREMIUM_REQUIRED' using errcode='42501'; end if;
 if p_watching is null or not vnext_private.member_allowed(p_observation_id,true) then raise exception 'OBSERVATION_UNAVAILABLE' using errcode='42501'; end if;
 perform pg_advisory_xact_lock(hashtextextended('vnext-watch:'||auth.uid()::text,0));
 select watching into previous from vnext_private.member_watch_events where user_id=auth.uid() and observation_id=p_observation_id order by id desc limit 1;
 if coalesce(previous,false)<>p_watching then
  select count(*) into n from (select distinct on(observation_id) watching from vnext_private.member_watch_events where user_id=auth.uid() order by observation_id,id desc)x where watching;
  if p_watching and n>=200 then raise exception 'WATCHLIST_LIMIT'; end if;
  insert into vnext_private.member_watch_events(user_id,observation_id,watching) values(auth.uid(),p_observation_id,p_watching);
 end if;
 return jsonb_build_object('saved',p_watching);
end $$;
revoke all on function public.set_vnext_watch_v1(text,boolean) from public,anon,authenticated,service_role;
grant execute on function public.set_vnext_watch_v1(text,boolean) to authenticated;
comment on schema vnext_private is 'Unreleased VNext research candidate. No Production writers, Cron, or automatic publication.';
commit;

-- CANDIDATE ONLY. Requires both earlier VNext candidates; never applies itself.
-- Independent server review -> explicit Owner approval -> published projection.
begin;
create table vnext_private.publication_reviews(
 id uuid primary key default gen_random_uuid(),
 observation_id text not null references vnext_private.stock_horizon_observations(id),
 snapshot_hash text not null check(snapshot_hash ~ '^[a-f0-9]{64}$'),
 review_hash text not null unique check(review_hash ~ '^[a-f0-9]{64}$'),
 review_version text not null check(length(review_version)>0),
 reviewer_ref text not null check(length(reviewer_ref)>0),
 quality text not null check(quality in ('PASS','FAIL','PENDING')),
 time_status text not null check(time_status in ('PASS','FAIL','PENDING')),
 licensing text not null check(licensing in ('PASS','FAIL','PENDING')),
 quality_document_hash text not null check(quality_document_hash ~ '^[a-f0-9]{64}$'),
 time_document_hash text not null check(time_document_hash ~ '^[a-f0-9]{64}$'),
 license_document_hash text not null check(license_document_hash ~ '^[a-f0-9]{64}$'),
 evidence_set_hash text not null check(evidence_set_hash ~ '^[a-f0-9]{64}$'),
 free_allowed boolean not null default false, premium_allowed boolean not null default false,
 reason text not null check(length(reason)>0), primary_risk text not null check(length(primary_risk)>0),
 supporting_ids text[] not null, contradicting_ids text[] not null,
 event_ids text[] not null default '{}', relation_ids text[] not null default '{}',
 reviewed_at timestamptz not null default clock_timestamp(),
 expires_at timestamptz not null, recorded_at timestamptz not null default clock_timestamp(),
 check(reviewed_at<=recorded_at and expires_at>reviewed_at)
);
create table vnext_private.owner_publication_events(
 id bigint generated always as identity primary key,
 request_key uuid not null unique,
 observation_id text not null references vnext_private.stock_horizon_observations(id),
 review_id uuid not null references vnext_private.publication_reviews(id),
 actor uuid not null references auth.users(id),
 action text not null check(action in ('APPROVE','REVOKE')),
 audience text not null check(audience in ('free','premium')),
 publication_id bigint not null unique references vnext_private.publication_audit(id),
 occurred_at timestamptz not null default clock_timestamp()
);
create index vnext_review_latest on vnext_private.publication_reviews(observation_id,recorded_at desc,id);
create index vnext_owner_publication_latest on vnext_private.owner_publication_events(observation_id,id desc);
do $$ declare n text; begin
 foreach n in array array['publication_reviews','owner_publication_events'] loop
  execute format('alter table vnext_private.%I enable row level security',n);
  execute format('alter table vnext_private.%I force row level security',n);
  execute format('revoke all on vnext_private.%I from public,anon,authenticated,service_role',n);
  execute format('create trigger immutable before update or delete on vnext_private.%I for each row execute function vnext_private.immutable_record()',n);
 end loop;
end $$;
-- Registry importer is a trusted server process, not the selector or browser.
-- No grants/approvals, synthetic records or historical cards are seeded here.
grant select,insert on vnext_private.publication_reviews to service_role;

create function vnext_private.publication_evidence_hash(p_id text) returns text
language sql stable security definer set search_path='' as $$
 select encode(sha256(convert_to(coalesce(string_agg(e.id||':'||e.snapshot_hash,',' order by e.id),''),'UTF8')),'hex')
 from vnext_private.observation_evidence x join vnext_private.event_sources e on e.id=x.evidence_id
 where x.observation_id=p_id;
$$;
revoke all on function vnext_private.publication_evidence_hash(text) from public,anon,authenticated,service_role;
create function vnext_private.validate_publication_review() returns trigger
language plpgsql security definer set search_path='' as $$
declare o vnext_private.stock_horizon_observations;
begin
 perform pg_advisory_xact_lock(hashtextextended('vnext-member-publication',0));
 select * into strict o from vnext_private.stock_horizon_observations where id=new.observation_id;
 if new.recorded_at>clock_timestamp() or new.reviewed_at<o.created_at
  or new.reviewer_ref=o.strategy_version or new.snapshot_hash<>o.snapshot_hash
  or new.evidence_set_hash<>vnext_private.publication_evidence_hash(o.id)
  or cardinality(new.supporting_ids)=0 or cardinality(new.contradicting_ids)=0
  or new.supporting_ids && new.contradicting_ids
  or exists(select from unnest(new.supporting_ids||new.contradicting_ids) eid where not exists(
   select from vnext_private.observation_evidence x where x.observation_id=o.id and x.evidence_id=eid))
 then raise exception 'INDEPENDENT_REVIEW_INVALID'; end if;
 -- Server receipt time is authoritative; caller cannot backdate revision order.
 new.recorded_at:=clock_timestamp();
 return new;
end $$;
revoke all on function vnext_private.validate_publication_review() from public,anon,authenticated,service_role;
create trigger validate_review before insert on vnext_private.publication_reviews
 for each row execute function vnext_private.validate_publication_review();

-- Non-approval checks are identical to the existing conservative gate.
create function vnext_private.publication_preflight(p_id text,p_now timestamptz) returns boolean
language sql stable security definer set search_path='' as $$
 select exists(select from vnext_private.stock_horizon_observations o
 where o.id=p_id and o.mode='FORWARD_SHADOW' and o.status in ('WATCHING','CONDITION_MET')
 and o.created_at<=p_now and o.next_review_at>p_now and o.expires_at>p_now
 and o.reason !~ '(保證|穩賺|必漲|必賺|高勝率|正式推薦|買進訊號)'
 and not exists(select from jsonb_array_elements(o.confirmation_conditions||o.invalidation_conditions) c
   where coalesce(c->>'text','')='' or c->>'text' ~ '(保證|穩賺|必漲|必賺|高勝率|正式推薦|買進訊號)'
   or coalesce(c->>'state','') not in ('CONFIRMED','NOT_MET','UNKNOWN')
   or jsonb_typeof(c->'evidence_ids') is distinct from 'array'
   or coalesce(jsonb_array_length(c->'evidence_ids'),0)=0
   or exists(select from jsonb_array_elements_text(c->'evidence_ids') cid where not exists(
     select from vnext_private.observation_evidence x where x.observation_id=o.id and x.evidence_id=cid)))
 and not exists(select from jsonb_array_elements(o.invalidation_conditions) c where c->>'state'='CONFIRMED')
 and (o.status<>'CONDITION_MET' or (not exists(select from jsonb_array_elements(o.confirmation_conditions) c where c->>'state'<>'CONFIRMED')
   and not exists(select from jsonb_array_elements(o.invalidation_conditions) c where c->>'state'<>'NOT_MET')))
 and exists(select from vnext_private.observation_evidence x where x.observation_id=o.id)
 and not exists(select from vnext_private.observation_evidence x join vnext_private.event_sources e on e.id=x.evidence_id
   join vnext_private.source_licenses l on l.id=e.license_id where x.observation_id=o.id and
   (e.symbol<>o.symbol or e.quality<>'PASS' or not e.relevant or e.available_at>o.created_at or e.last_verified_at>o.created_at
    or e.valid_until<=o.created_at or not l.storage_allowed or not l.derived_allowed or not l.commercial_allowed
    or not l.redistribution_allowed or l.reviewed_at>p_now or (l.expires_at is not null and l.expires_at<=p_now)))
 and not exists(select from unnest(case o.horizon
   when 'SHORT' then array['PRICE_VOLUME','INSTITUTIONAL','NEWS','TECHNICAL_STRUCTURE']
   when 'MEDIUM' then array['REVENUE','ORDERS','GUIDANCE','INSTITUTIONAL','INDUSTRY_EVENT']
   else array['DEMAND','MOAT','SUPPLY_CHAIN','EPS','MARGIN','CAPEX','VALUATION'] end) k
   where not exists(select from vnext_private.observation_evidence x join vnext_private.event_sources e on e.id=x.evidence_id
     where x.observation_id=o.id and e.kind=k and e.classification='CONFIRMED_FACT')));
$$;
revoke all on function vnext_private.publication_preflight(text,timestamptz) from public,anon,authenticated,service_role;

-- The old gate remains intact, including quality, source rights and chronology.
alter function vnext_private.member_allowed(text,boolean) rename to legacy_member_allowed;
create function vnext_private.member_allowed(p_id text,p_history boolean default false) returns boolean
language sql stable security definer set search_path='' as $$
 select vnext_private.legacy_member_allowed(p_id,p_history) and exists(
  select from vnext_private.publication_reviews r
  join vnext_private.owner_publication_events a on a.review_id=r.id and a.observation_id=r.observation_id
  join vnext_private.member_copy c on c.publication_id=a.publication_id
  where r.observation_id=p_id and r.id=(select id from vnext_private.publication_reviews where observation_id=p_id order by recorded_at desc,id desc limit 1)
   and a.id=(select id from vnext_private.owner_publication_events where observation_id=p_id order by id desc limit 1)
   and a.action='APPROVE' and r.quality='PASS' and r.time_status='PASS' and r.licensing='PASS'
   and r.expires_at>now() and r.reviewed_at<=a.occurred_at
   and r.evidence_set_hash=vnext_private.publication_evidence_hash(p_id)
   and case a.audience when 'free' then r.free_allowed and r.premium_allowed else r.premium_allowed end);
$$;
revoke all on function vnext_private.member_allowed(text,boolean) from public,anon,authenticated,service_role;

create function public.review_vnext_publication_candidate_v1(p_observation_id text,p_review_id uuid,p_action text,p_audience text,p_request_key uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare r vnext_private.publication_reviews; o vnext_private.stock_horizon_observations;
 old vnext_private.owner_publication_events; pid bigint; event_id bigint; next_slot integer;
begin
 if auth.uid() is null or academy_private.access_v11() is distinct from 'owner' then raise exception 'OWNER_REQUIRED' using errcode='42501'; end if;
 if p_request_key is null or p_review_id is null or p_action is null or p_action not in('APPROVE','REVOKE')
  or p_audience is null or p_audience not in('free','premium') then raise exception 'REQUEST_INVALID'; end if;
 -- Serializes replay keys and the daily free edition; bounded tiny transaction.
 perform pg_advisory_xact_lock(hashtextextended('vnext-member-publication',0));
 select * into old from vnext_private.owner_publication_events where request_key=p_request_key;
 if found then
  if old.actor<>auth.uid() or old.observation_id<>p_observation_id or old.review_id<>p_review_id or old.action<>p_action or old.audience<>p_audience then raise exception 'IDEMPOTENCY_CONFLICT'; end if;
  return jsonb_build_object('event_id',old.id,'action',old.action,'replayed',true);
 end if;
 select * into strict o from vnext_private.stock_horizon_observations where id=p_observation_id;
 select * into strict r from vnext_private.publication_reviews where observation_id=o.id order by recorded_at desc,id desc limit 1;
 if r.id<>p_review_id then raise exception 'REVIEW_CHANGED'; end if;
 if p_action='APPROVE' and (r.quality<>'PASS' or r.time_status<>'PASS' or r.licensing<>'PASS'
  or r.expires_at<=now() or r.snapshot_hash<>o.snapshot_hash or r.evidence_set_hash<>vnext_private.publication_evidence_hash(o.id)
  or not r.premium_allowed or (p_audience='free' and not r.free_allowed)
  or not vnext_private.publication_preflight(o.id,now())) then raise exception 'PREREQUISITES_NOT_MET'; end if;
 insert into vnext_private.publication_audit(observation_id,snapshot_hash,audience,approved,content_kind,reviewer_ref,license_review_ref,gate_version)
 values(o.id,o.snapshot_hash,p_audience,p_action='APPROVE','RESEARCH_OBSERVATION',auth.uid()::text,r.license_document_hash,'VNEXT_PUBLICATION_1') returning id into pid;
 if p_action='APPROVE' then
  if exists(select from vnext_private.member_copy where observation_id=o.id) then raise exception 'NEW_IMMUTABLE_RESEARCH_VERSION_REQUIRED'; end if;
  -- Trigger independently checks unchanged evidence, publication and source gate.
  insert into vnext_private.member_copy(observation_id,publication_id,primary_risk,supporting_ids,contradicting_ids,event_ids,relation_ids)
  values(o.id,pid,r.primary_risk,r.supporting_ids,r.contradicting_ids,r.event_ids,r.relation_ids);
  if p_audience='free' and not exists(select from vnext_private.member_daily_edition where business_date=(now() at time zone 'Asia/Taipei')::date and symbol=o.symbol) then
   select coalesce(max(slot),0)+1 into next_slot from vnext_private.member_daily_edition where business_date=(now() at time zone 'Asia/Taipei')::date;
   if next_slot<=3 then insert into vnext_private.member_daily_edition(business_date,slot,symbol) values((now() at time zone 'Asia/Taipei')::date,next_slot,o.symbol); end if;
  end if;
 end if;
 insert into vnext_private.owner_publication_events(request_key,observation_id,review_id,actor,action,audience,publication_id)
 values(p_request_key,o.id,r.id,auth.uid(),p_action,p_audience,pid) returning id into event_id;
 return jsonb_build_object('event_id',event_id,'action',p_action,'replayed',false);
end $$;
revoke all on function public.review_vnext_publication_candidate_v1(text,uuid,text,text,uuid) from public,anon,authenticated,service_role;
grant execute on function public.review_vnext_publication_candidate_v1(text,uuid,text,text,uuid) to authenticated;

create function public.get_owner_vnext_publication_review_v1() returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare rows jsonb;
begin
 if auth.uid() is null or academy_private.access_v11() is distinct from 'owner' then raise exception 'OWNER_REQUIRED' using errcode='42501'; end if;
 select coalesce(jsonb_agg(to_jsonb(x)),'[]') into rows from (
  select o.id,o.symbol,o.company,o.horizon,o.reason,o.created_at,o.next_review_at,
   r.id as review_id,r.quality,r.time_status,r.licensing,r.reason as review_reason,r.primary_risk,
   coalesce(r.quality='PASS' and r.time_status='PASS' and r.licensing='PASS' and r.expires_at>now() and o.next_review_at>now() and o.expires_at>now()
    and o.mode='FORWARD_SHADOW' and r.premium_allowed and vnext_private.publication_preflight(o.id,now())
    and not exists(select from vnext_private.member_copy c where c.observation_id=o.id),false) as prerequisites_ready,
   exists(select from vnext_private.member_copy c where c.observation_id=o.id) and not vnext_private.member_allowed(o.id,true) as requires_new_version,
   coalesce(r.free_allowed,false) as free_allowed,
   vnext_private.member_allowed(o.id,true) as published,
   vnext_private.member_allowed(o.id,false) as current
  from vnext_private.stock_horizon_observations o left join lateral(
   select * from vnext_private.publication_reviews where observation_id=o.id order by recorded_at desc,id desc limit 1)r on true
  order by o.created_at desc,o.id limit 216
 )x;
 return jsonb_build_object('rows',rows,'publication_requires_owner',true);
end $$;
revoke all on function public.get_owner_vnext_publication_review_v1() from public,anon,authenticated,service_role;
grant execute on function public.get_owner_vnext_publication_review_v1() to authenticated;

-- Additive endpoint: older member readers keep their original response shape.
-- Free history is only the brief from the exact originally approved free
-- edition, not all old research or Premium evidence. Rights/revocation are
-- checked again on every read, including after subscription changes.
create function public.get_vnext_free_history_v1() returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare history jsonb;
begin
 if auth.uid() is null or academy_private.access_v11() is distinct from 'free' then
  raise exception 'FREE_MEMBER_REQUIRED' using errcode='42501';
 end if;
 select coalesce(jsonb_agg(vnext_private.member_card(x.id,false) order by x.created_at desc,x.id),'[]') into history
 from (
  select o.id,o.created_at from vnext_private.stock_horizon_observations o
  join vnext_private.member_copy c on c.observation_id=o.id
  where not vnext_private.member_allowed(o.id,false) and vnext_private.member_allowed(o.id,true)
  and exists(select from vnext_private.owner_publication_events a
   join vnext_private.member_daily_edition d on d.business_date=(a.occurred_at at time zone 'Asia/Taipei')::date and d.symbol=o.symbol
   where a.observation_id=o.id and a.publication_id=c.publication_id and a.action='APPROVE' and a.audience='free')
  order by o.created_at desc,o.id limit 100
 )x;
 return jsonb_build_object('schema','VNEXT_FREE_HISTORY_V1','history',history);
end $$;
revoke all on function public.get_vnext_free_history_v1() from public,anon,authenticated,service_role;
grant execute on function public.get_vnext_free_history_v1() to authenticated;
commit;

-- CANDIDATE ONLY. Applying this file does NOT activate the new policy.
-- A separately approved, service-only activation records the actual DB time.
begin;
create schema membership_private;
revoke all on schema membership_private from public, anon, authenticated, service_role;

create table membership_private.policy_versions (
  version text primary key check (version = 'LEGACY_GRANDFATHER_V1'),
  effective_at timestamptz not null,
  approval_reference text not null check (length(approval_reference) between 8 and 200),
  previous_offer jsonb not null,
  created_at timestamptz not null default clock_timestamp()
);
create table membership_private.legacy_snapshots (
  -- No FK cascade/restrict: do not change existing Auth account deletion rules.
  user_id uuid primary key,
  policy_version text not null references membership_private.policy_versions(version),
  account_created_at timestamptz not null,
  captured_at timestamptz not null,
  basis text not null check (basis in ('CANONICAL_ENTITLEMENT','LEGACY_PROFILE','OWNER_ROLE','NO_ACQUIRED_ENTITLEMENT')),
  review_status text not null check (review_status in ('EXPLICIT_TERM','EXPLICIT_PERMANENT','LEGACY_POLICY_REVIEW_REQUIRED','NO_ACTIVE_GRANT')),
  evidence jsonb not null,
  evidence_hash text not null check (evidence_hash ~ '^[a-f0-9]{64}$')
);
alter table membership_private.policy_versions enable row level security;
alter table membership_private.legacy_snapshots enable row level security;
revoke all on all tables in schema membership_private from public, anon, authenticated, service_role;

create function membership_private.reject_rewrite_v1() returns trigger
language plpgsql set search_path = '' as $$begin raise exception 'IMMUTABLE_MEMBERSHIP_POLICY';end$$;
revoke all on function membership_private.reject_rewrite_v1() from public, anon, authenticated, service_role;
create trigger policy_immutable before update or delete on membership_private.policy_versions
for each row execute function membership_private.reject_rewrite_v1();
create trigger legacy_immutable before update or delete on membership_private.legacy_snapshots
for each row execute function membership_private.reject_rewrite_v1();

-- Extend configuration vocabulary only; keep its current row and billing mode.
alter table public.membership_access_config drop constraint membership_access_config_signup_mode_check;
alter table public.membership_access_config add constraint membership_access_config_signup_mode_check
check (signup_mode in ('closed','beta_full','trialing','free'));

-- Keep the exact legacy implementation private. Existing callers such as
-- get-report-payload keep the same public RPC contract, but cannot accidentally
-- grant Beta to new Free accounts after policy activation. No Report code edit.
alter function public.ensure_member_entitlement_v1(uuid) set schema membership_private;
alter function membership_private.ensure_member_entitlement_v1(uuid) rename to ensure_member_entitlement_pre_policy_v1;
revoke all on function membership_private.ensure_member_entitlement_pre_policy_v1(uuid) from public,anon,authenticated,service_role;

create function public.activate_membership_policy_candidate_v1(p_approval_reference text)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  v_policy membership_private.policy_versions%rowtype;
  v_config public.membership_access_config%rowtype;
  v_now timestamptz;
  r record;
  v_evidence jsonb;
  v_basis text;
  v_review text;
  v_state text;
  v_tier text;
begin
  if p_approval_reference is null or length(btrim(p_approval_reference)) not between 8 and 200 then
    raise exception 'EXPLICIT_RELEASE_APPROVAL_REQUIRED';
  end if;
  -- Global exclusive/shared lock orders policy activation before per-user work.
  perform pg_catalog.pg_advisory_xact_lock(67230130);
  select * into v_policy from membership_private.policy_versions;
  if found then
    if v_policy.approval_reference <> p_approval_reference then raise exception 'POLICY_ALREADY_ACTIVATED';end if;
    return jsonb_build_object('version',v_policy.version,'effective_at',v_policy.effective_at,'replayed',true);
  end if;
  -- Brief maintenance transaction: no account/profile/entitlement can slip
  -- between the cutoff and its snapshot. No email or provider payload is copied.
  lock table auth.users, public.profiles in share mode;
  lock table public.member_entitlements in share row exclusive mode;
  select * into strict v_config from public.membership_access_config where config_key='primary' for update;
  if v_config.billing_mode <> 'disabled' then raise exception 'PAYMENT_PROVIDER_REVIEW_REQUIRED';end if;
  if exists(select 1 from auth.users u left join public.profiles p on p.id=u.id
    where not coalesce(u.is_anonymous,false) and p.id is null) then
    raise exception 'LEGACY_PROFILE_MISSING';
  end if;
  v_now := clock_timestamp();
  insert into membership_private.policy_versions(version,effective_at,approval_reference,previous_offer)
  values('LEGACY_GRANDFATHER_V1',v_now,p_approval_reference,
    jsonb_build_object('signup_mode',v_config.signup_mode,'trial_days',v_config.trial_days,
      'beta_access_ends_at',v_config.beta_access_ends_at,'billing_mode',v_config.billing_mode));
  for r in select u.id,u.created_at,p.role,p.subscription_status,p.membership_tier,p.paid_until,
      e.user_id as entitlement_id,e.state,e.tier,e.source,e.version,e.access_started_at,e.access_ends_at,
      e.trial_started_at,e.trial_ends_at,e.current_period_end,e.cancel_at_period_end,
      e.metadata->>'permanent' as explicit_permanent
    from auth.users u join public.profiles p on p.id=u.id
    left join public.member_entitlements e on e.user_id=u.id
    where not coalesce(u.is_anonymous,false) and u.created_at<=v_now order by u.id
  loop
    v_basis := case when r.entitlement_id is not null then 'CANONICAL_ENTITLEMENT'
      when lower(coalesce(r.role,''))='admin' then 'OWNER_ROLE'
      when lower(coalesce(r.subscription_status,''))='active' then 'LEGACY_PROFILE'
      else 'NO_ACQUIRED_ENTITLEMENT' end;
    v_review := case
      when v_basis='OWNER_ROLE' or (r.state='owner' and r.explicit_permanent='true') then 'EXPLICIT_PERMANENT'
      when r.entitlement_id is not null and r.explicit_permanent='true' then 'EXPLICIT_PERMANENT'
      when r.entitlement_id is not null and coalesce(r.trial_ends_at,r.access_ends_at,r.current_period_end) is not null then 'EXPLICIT_TERM'
      when v_basis='LEGACY_PROFILE' and r.paid_until is not null then 'EXPLICIT_TERM'
      when v_basis in ('LEGACY_PROFILE','CANONICAL_ENTITLEMENT') then 'LEGACY_POLICY_REVIEW_REQUIRED'
      else 'NO_ACTIVE_GRANT' end;
    v_evidence := jsonb_build_object('profile_role',r.role,'profile_subscription_status',r.subscription_status,
      'profile_membership_tier',r.membership_tier,'profile_paid_until',r.paid_until,
      'state',r.state,'tier',r.tier,'source',r.source,'source_version',r.version,
      'access_started_at',r.access_started_at,'access_ends_at',r.access_ends_at,
      'trial_started_at',r.trial_started_at,'trial_ends_at',r.trial_ends_at,
      'current_period_end',r.current_period_end,'cancel_at_period_end',r.cancel_at_period_end,
      'explicit_permanent',r.explicit_permanent,'payment_verified',false);
    insert into membership_private.legacy_snapshots
      values(r.id,'LEGACY_GRANDFATHER_V1',r.created_at,v_now,v_basis,v_review,v_evidence,
        encode(sha256(convert_to(v_evidence::text,'UTF8')),'hex'));
    -- Existing canonical rows are NEVER rewritten. Materialize only previously
    -- effective profile grants, so later logins cannot reinterpret them as trial.
    if r.entitlement_id is null and (v_basis='OWNER_ROLE' or
      (v_basis='LEGACY_PROFILE' and (r.paid_until is null or r.paid_until>v_now))) then
      v_state := case when v_basis='OWNER_ROLE' then 'owner' when r.paid_until is null then 'beta_full' else 'paid_active' end;
      v_tier := case when v_basis='OWNER_ROLE' then 'admin' when lower(coalesce(r.role,''))='vip' then 'vip'
        when lower(coalesce(r.role,''))='member' then 'member' when lower(coalesce(r.membership_tier,''))='vip' then 'vip' else 'member' end;
      insert into public.member_entitlements(user_id,state,tier,source,access_started_at,access_ends_at,metadata)
      values(r.id,v_state,v_tier,case when v_basis='OWNER_ROLE' then 'owner' else 'manual' end,v_now,
        case when v_basis='OWNER_ROLE' then null else r.paid_until end,
        jsonb_build_object('policy_version','LEGACY_GRANDFATHER_V1','legacy_basis',v_basis,
          'legacy_review_status',v_review,'original_start_unknown',true,'payment_verified',false));
      insert into public.membership_access_events(user_id,from_state,to_state,event_type,source,metadata)
      values(r.id,null,v_state,'legacy_grant_preserved','policy',jsonb_build_object('policy_version','LEGACY_GRANDFATHER_V1','review_status',v_review));
    end if;
  end loop;
  update public.membership_access_config set signup_mode='free',metadata=metadata||
    jsonb_build_object('policy_version','LEGACY_GRANDFATHER_V1','membership_policy_effective_at',v_now)
    where config_key='primary';
  return jsonb_build_object('version','LEGACY_GRANDFATHER_V1','effective_at',v_now,'replayed',false,
    'legacy_count',(select count(*) from membership_private.legacy_snapshots),
    'review_required',(select count(*) from membership_private.legacy_snapshots where review_status='LEGACY_POLICY_REVIEW_REQUIRED'));
end$$;
revoke all on function public.activate_membership_policy_candidate_v1(text) from public,anon,authenticated;
grant execute on function public.activate_membership_policy_candidate_v1(text) to service_role;

-- Same response contract. Before approved activation, exactly the existing
-- activation path. Afterwards: no auto trial, no login-time grant rewriting.
create function public.ensure_member_entitlement_v2(p_user_id uuid)
returns public.member_entitlements language plpgsql security definer set search_path = '' as $$
declare v_row public.member_entitlements%rowtype;v_role text;
begin
  perform pg_catalog.pg_advisory_xact_lock_shared(67230130);
  if not exists(select 1 from membership_private.policy_versions) then
    return membership_private.ensure_member_entitlement_pre_policy_v1(p_user_id);
  end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_user_id::text,0));
  select role into v_role from public.profiles where id=p_user_id;
  if not found then raise exception 'profile not found';end if;
  select * into v_row from public.member_entitlements where user_id=p_user_id;
  if found then return v_row;end if;
  if lower(coalesce(v_role,''))='admin' then return membership_private.ensure_member_entitlement_pre_policy_v1(p_user_id);end if;
  return null;
end$$;
revoke all on function public.ensure_member_entitlement_v2(uuid) from public,anon,authenticated;
grant execute on function public.ensure_member_entitlement_v2(uuid) to service_role;
create function public.ensure_member_entitlement_v1(p_user_id uuid)
returns public.member_entitlements language sql security definer set search_path = '' as $$
  select public.ensure_member_entitlement_v2(p_user_id)
$$;
revoke all on function public.ensure_member_entitlement_v1(uuid) from public,anon,authenticated;
grant execute on function public.ensure_member_entitlement_v1(uuid) to service_role;
create function public.get_member_policy_receipt_v1(p_user_id uuid)
returns jsonb language sql stable security definer set search_path = '' as $$
  select jsonb_build_object('legacy_review_required',exists(select 1 from membership_private.legacy_snapshots
    where user_id=p_user_id and review_status='LEGACY_POLICY_REVIEW_REQUIRED'),
    'policy_active',exists(select 1 from membership_private.policy_versions))
$$;
revoke all on function public.get_member_policy_receipt_v1(uuid) from public,anon,authenticated;
grant execute on function public.get_member_policy_receipt_v1(uuid) to service_role;
-- A future billing callback must not silently replace an independently held
-- legacy grant. Preserve its minimum tier/window; unknown terms require review.
-- This is not a refund policy or a provider signature validator.
create function membership_private.protect_legacy_grant_v1() returns trigger
language plpgsql security definer set search_path = '' as $$
declare s membership_private.legacy_snapshots%rowtype;floor_end timestamptz;floor_tier text;floor_active boolean;new_end timestamptz;new_active boolean;
begin
  select * into s from membership_private.legacy_snapshots where user_id=old.user_id;
  if not found then return new;end if;
  floor_tier := coalesce(s.evidence->>'tier',nullif(s.evidence->>'profile_role','free'),s.evidence->>'profile_membership_tier','member');
  floor_end := case when s.basis='LEGACY_PROFILE' then (s.evidence->>'profile_paid_until')::timestamptz
    when s.evidence->>'state'='trialing' then (s.evidence->>'trial_ends_at')::timestamptz
    else coalesce((s.evidence->>'access_ends_at')::timestamptz,(s.evidence->>'current_period_end')::timestamptz) end;
  floor_active := s.basis='OWNER_ROLE' or s.evidence->>'state'='owner' or
    (s.basis='LEGACY_PROFILE' and (floor_end is null or floor_end>clock_timestamp())) or
    (s.evidence->>'state' in ('paid_active','beta_full') and (floor_end is null or floor_end>clock_timestamp())) or
    (s.evidence->>'state' in ('trialing','canceled') and floor_end>clock_timestamp());
  if not coalesce(floor_active,false) then return new;end if;
  new_end := case when new.state='trialing' then new.trial_ends_at else coalesce(new.access_ends_at,new.current_period_end) end;
  new_active := new.state='owner' or (new.state in ('paid_active','beta_full') and (new_end is null or new_end>clock_timestamp()))
    or (new.state in ('trialing','canceled') and new_end>clock_timestamp());
  if not coalesce(new_active,false) or
    (floor_end is null and new_end is not null) or
    (floor_end is not null and new_end is not null and new_end<floor_end) or
    (floor_tier='admin' and new.state<>'owner') or
    (floor_tier='vip' and new.tier not in ('vip','admin')) then
    raise exception 'LEGACY_GRANT_REVIEW_REQUIRED';
  end if;
  return new;
end$$;
revoke all on function membership_private.protect_legacy_grant_v1() from public,anon,authenticated,service_role;
create trigger preserve_legacy_grant_v1 before update on public.member_entitlements
for each row execute function membership_private.protect_legacy_grant_v1();
comment on function public.activate_membership_policy_candidate_v1(text) is
  'CANDIDATE: separately approved activation only. Database clock cutoff; immutable snapshots; no payment activation.';
commit;
